import js from '@eslint/js';
import importX, { createNodeResolver } from 'eslint-plugin-import-x';
import globals from 'globals';
// Generated by `wxt prepare` (runs automatically from the postinstall script),
// so this file only resolves after `npm ci`. Replaces a hand-kept list of the
// globals WXT injects at build time.
import wxtAutoImports from './.wxt/eslint-auto-imports.mjs';

// Only correctness rules here. Formatting belongs to prettier (`npm run format`),
// so nothing in this file is about style.
export default [
  {
    ignores: ['.wxt/', '.output/', 'node_modules/', 'test/docker/', '*.svg'],
  },
  js.configs.recommended,
  {
    files: ['**/*.{js,jsx}'],
    languageOptions: {
      ecmaVersion: 'latest',
      sourceType: 'module',
      parserOptions: { ecmaFeatures: { jsx: true } },
      globals: {
        ...globals.browser,
        ...globals.webextensions,
      },
    },
    plugins: { 'import-x': importX },
    settings: {
      // Resolve the `~/...` alias through the paths WXT generates, so a typo in
      // an import path is a lint error instead of a broken build.
      'import-x/resolver-next': [
        createNodeResolver({
          tsconfig: { configFile: '.wxt/tsconfig.json' },
          extensions: ['.js', '.jsx', '.json', '.css'],
        }),
      ],
    },
    rules: {
      // `#imports` is a WXT build-time alias, not a real package.
      'import-x/no-unresolved': ['error', { ignore: ['^#imports$'] }],
      'import-x/no-duplicates': 'error',
      'no-unused-vars': [
        'error',
        {
          // Callbacks here follow browser/downloader API signatures whose
          // trailing arguments are often irrelevant, and src/downloader/index.js
          // declares the client interface with parameters its subclasses use.
          args: 'none',
          // `const { formatted, ...rest } = entry` is how this repo drops a key.
          ignoreRestSiblings: true,
          varsIgnorePattern: '^_',
          caughtErrors: 'none',
        },
      ],
      // Established idiom in the adapters: `const [, id] = href.match(..) ?? [, '']`
      // destructures past group 0 with a fallback. Elisions are never read here.
      'no-sparse-arrays': 'off',
      'no-empty': ['error', { allowEmptyCatch: true }],
      'no-constant-condition': ['error', { checkLoops: false }],
    },
  },
  {
    // Config files and tests run in Node, not the browser.
    files: ['*.config.js', 'vitest.setup.js', 'src/**/__tests__/**/*.js'],
    languageOptions: { globals: { ...globals.node } },
  },
  {
    // Entrypoints may use WXT's auto-imports (the generated globals object).
    files: ['src/entrypoints/**/*.js'],
    ...wxtAutoImports,
  },
];
